// Keep the child's design on this device; never send names or drawings to a server.
const rocketColors=['#f06450','#52b8d9','#a78be0','#f4c64e','#ffffff','#32517a'];
let rocketDesign=store.get('pp-rocket-v1',null);
if(!rocketDesign||!Array.isArray(rocketDesign.strokes))rocketDesign={name:'',color:rocketColors[0],strokes:[],ready:false};
rocketDesign.name=String(rocketDesign.name||'').slice(0,24);
if(!rocketColors.includes(rocketDesign.color))rocketDesign.color=rocketColors[0];
rocketDesign.strokes=rocketDesign.strokes.filter(s=>s&&rocketColors.includes(s.color)&&Array.isArray(s.points)).slice(-300).map(s=>({color:s.color,part:s.part,points:s.points.filter(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)).slice(0,500)}));
const rocketSheet=new Image();rocketSheet.src='assets/story-characters.png';
function saveRocket(){try{localStorage.setItem('pp-rocket-v1',JSON.stringify(rocketDesign));return true}catch{return false}}
function paintRocket(canvas,part=null){const c=canvas.getContext('2d');c.clearRect(0,0,300,360);if(rocketSheet.complete&&rocketSheet.naturalWidth)c.drawImage(rocketSheet,578,14,262,303,19,20,262,303);c.globalCompositeOperation='source-atop';c.globalAlpha=.27;c.fillStyle=rocketDesign.color;c.fillRect(0,0,300,360);c.globalAlpha=1;c.globalCompositeOperation='source-over';for(const s of rocketDesign.strokes){c.strokeStyle=s.color;c.lineWidth=9;c.lineCap='round';c.lineJoin='round';c.beginPath();s.points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();}if(part!==null){c.strokeStyle='#fff9c6';c.lineWidth=2;c.setLineDash([6,6]);const zones=[[86,95,127,165],[95,22,110,85],[30,215,240,95]];c.strokeRect(...zones[part]);c.setLineDash([])}}
function rocketPicture(){if(!rocketDesign.ready)return pic('rocket');const canvas=document.createElement('canvas');canvas.width=300;canvas.height=360;paintRocket(canvas);return `<img class="custom-rocket" alt="Your decorated rocket" src="${canvas.toDataURL()}">`}
function openRocketWorkshop(){const stage=$('#illStage');stage.classList.add('workshop-stage');stage.innerHTML=`<div class="workshop"><div class="workshop-heading"><div><span class="eyebrow">YOUR ROCKET WORKSHOP</span><h3>Make a rocket only you could make.</h3></div><span id="designSave" role="status"></span></div><div class="workshop-layout"><div class="blueprint"><canvas id="rocketCanvas" width="300" height="360" aria-label="Draw decorations on your rocket with your finger or mouse"></canvas><span class="blueprint-caption">Designed by you, flown by Johnny and Pip</span></div><div class="workshop-tools"><div class="part-tabs" aria-label="Rocket parts">${['Body','Nose','Fins'].map((p,i)=>`<button data-part="${i}" aria-pressed="${i===0}">${p}</button>`).join('')}</div><p id="drawHint">Draw stripes, dots, or anything you like on the body.</p><div class="paint-colors" aria-label="Paint colors">${rocketColors.map((c,i)=>`<button style="--paint:${c}" data-paint="${c}" aria-label="${['Coral','Blue','Purple','Yellow','White','Navy'][i]} paint" aria-pressed="${i===0}"></button>`).join('')}</div><div class="tool-row"><button id="paintPart">Paint this part</button><button id="undoPaint">Undo</button></div><button id="nextPart">Next part</button><label class="rocket-name">What is your rocket called?<input id="rocketName" maxlength="24" placeholder="e.g. Moonberry" autocomplete="off"></label><button id="readyRocket" class="primary">Put my rocket in the story</button><p class="workshop-note">Draw with a finger or mouse, or use the paint buttons. Your design stays on this device.</p></div></div></div>`;
let part=0,ink=rocketColors[0],active=null;const canvas=$('#rocketCanvas');const redraw=()=>paintRocket(canvas,part);const persist=()=>{$('#designSave').textContent=saveRocket()?'Design saved':'Kept for this visit';};
rocketSheet.decode().then(()=>{if(canvas.isConnected)redraw()}).catch(()=>{});redraw();$('#rocketName').value=rocketDesign.name;
const selectPart=i=>{part=i;stage.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.part)===i));$('#drawHint').textContent=['Draw stripes, dots, or anything you like on the body.','Give the nose a bright color for its journey through the stars.','Decorate the fins so you can spot your rocket on Mars.'][i];$('#nextPart').textContent=i===2?'Back to body':'Next part';redraw()};
stage.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>selectPart(Number(b.dataset.part)));$('#nextPart').onclick=()=>selectPart((part+1)%3);stage.querySelectorAll('[data-paint]').forEach(b=>b.onclick=()=>{ink=b.dataset.paint;stage.querySelectorAll('[data-paint]').forEach(p=>p.setAttribute('aria-pressed',p===b))});
const addStroke=s=>{rocketDesign.strokes.push(s);if(rocketDesign.strokes.length>300)rocketDesign.strokes.shift()};
$('#paintPart').onclick=()=>{const shapes=[[[115,125],[185,125],[115,155],[185,155],[115,185],[185,185]],[[140,60],[160,60],[150,42],[140,60]],[[48,265],[80,240],[68,285],[48,265],[228,240],[250,265],[232,285]]];addStroke({color:ink,part,points:shapes[part]});redraw();persist()};
$('#undoPaint').onclick=()=>{rocketDesign.strokes.pop();redraw();persist()};
const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(300,(e.clientX-r.left)*300/r.width)),Math.max(0,Math.min(360,(e.clientY-r.top)*360/r.height))]};
canvas.onpointerdown=e=>{if(active!==null)return;e.preventDefault();active=e.pointerId;canvas.setPointerCapture(e.pointerId);const p=point(e);addStroke({color:ink,part,points:[p,[p[0]+.1,p[1]+.1]]});redraw()};canvas.onpointermove=e=>{if(active!==e.pointerId)return;const points=rocketDesign.strokes.at(-1).points;if(points.length<500)points.push(point(e));redraw()};const end=e=>{if(e.pointerId!==active)return;active=null;persist()};canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onlostpointercapture=end;
$('#rocketName').oninput=e=>{rocketDesign.name=e.target.value.slice(0,24);persist()};
$('#readyRocket').onclick=()=>{rocketDesign.ready=true;if(!rocketDesign.name.trim())rocketDesign.name='Star Hopper';persist();drawPage()};persist();
}
rocketSheet.addEventListener('load',()=>{document.querySelectorAll('.custom-rocket').forEach(img=>{const c=document.createElement('canvas');c.width=300;c.height=360;paintRocket(c);img.src=c.toDataURL()})});
